```ts
import { sleep, generateId, isRecord } from '@gentleduck/upload/core'

// Delay execution
await sleep(1000)

// Generate a unique ID
const id = generateId()

// Type-safe object check
if (isRecord(value)) {
  // value is Record<string, unknown>
}
```

