const store = createUploadStore({
  api: photoDuckApi,
  strategies: photoDuckStrategies,
  plugins: [
    createImageMetadataPlugin(),
    createAnalyticsPlugin({ endpoint: '/api/metrics' }),
    createAutoStartPlugin(),
  ],

